    28  static void ns_free(Sdb *s, SdbList *list) {
    29          SdbListIter next;
    30          SdbListIter *it;
    31          int deleted;
    32          SdbNs *ns;
    33          if (!list || !s) {
    34                  return;
    35          }
    36          // TODO: Implement and use ls_foreach_safe
    37          if (in_list (list, s)) {
    38                  return;
    39          }
    40          ls_append (list, s);
    41          ls_foreach (s->ns, it, ns) {
    42                  deleted = 0;
    43                  next.n = it->n;
    44                  if (!in_list (list, ns)) {
    45                          ls_delete (s->ns, it); // free (it)
    46                          free (ns->name);
    47                          ns->name = NULL;
    48                          deleted = 1;
    49                          if (ns->sdb) {
    50                                  if (sdb_free (ns->sdb)) {
    51                                          ns->sdb = NULL;
    52                                          free (ns->name);
    53                                          ns->name = NULL;
    54                                  }
    55                          }
    56                          ls_append (list, ns);
    57                          ls_append (list, ns->sdb);
    58                          ns_free (ns->sdb, list);
    59                          sdb_free (ns->sdb);
    60                  }
    61                  if (!deleted) {
    62                          sdb_free (ns->sdb);
    63                          s->ns->free = NULL;
    64                          ls_delete (s->ns, it); // free (it)
    65                  }
    66                  free (ns);
    67                  it = &next;
    68          }
    69          ls_free (s->ns);
    70          s->ns = NULL;
    71  }
