   129  SDB_API bool sdb_ns_unset (Sdb *s, const char *name, Sdb *r) {
   130          SdbNs *ns;
   131          SdbListIter *it;
   132          if (s && (name || r)) {
   133                  ls_foreach (s->ns, it, ns) {
   134                          if (name && (!strcmp (name, ns->name))) {
