   147  SDB_API int sdb_ns_set (Sdb *s, const char *name, Sdb *r) {
   148          SdbNs *ns;
   149          SdbListIter *it;
   150          ut32 hash = sdb_hash (name);
   151          if (!s || !r || !name) {
   152                  return 0;
   153          }
   154          ls_foreach (s->ns, it, ns) {
   155                  if (ns->hash == hash) {
   156                          if (ns->sdb == r) {
   157                                  return 0;
   158                          }
   159                          sdb_free (ns->sdb);
   160                          r->refs++; // sdb_ref / sdb_unref //
   161                          ns->sdb = r;
   162                          return 1;
   163                  }
   164          }
   165          if (s->ns_lock) {
   166                  return 0;
   167          }
   168          ns = R_NEW (SdbNs);
   169          ns->name = strdup (name);
   170          ns->hash = hash;
   171          ns->sdb = r;
   172          r->refs++;
   173          ls_append (s->ns, ns);
   174          return 1;
   175  }
