   204  SDB_API Sdb *sdb_ns_path(Sdb *s, const char *path, int create) {
   205          char *ptr, *str;
   206          char *slash;
   207
   208          if (!s || !path || !*path)
   209                  return s;
   210          ptr = str = strdup (path);
   211          do {
   212                  slash = strchr (ptr, '/');
   213                  if (slash)
   214                          *slash = 0;
   215                  s = sdb_ns (s, ptr, create);
   216                  if (!s) break;
   217                  if (slash)
   218                          ptr = slash+1;
   219          } while (slash);
   220          free (str);
   221          return s;
   222  }
