   224  static void ns_sync (Sdb *s, SdbList *list) {
   225          SdbNs *ns;
   226          SdbListIter *it;
   227          ls_foreach (s->ns, it, ns) {
   228                  if (in_list (list, ns)) {
   229                          continue;
   230                  }
   231                  ls_append (list, ns);
   232                  ns_sync (ns->sdb, list);
   233                  sdb_sync (ns->sdb);
   234          }
   235          sdb_sync (s);
   236  }
